/* Gustavsvik data test. No credentials are embedded or persisted. */
const $=id=>document.getElementById(id);
const routeStorage=new URLSearchParams(location.search).has('test')?sessionStorage:localStorage;
const state={view:'overview',playing:false,progress:0,ready:false,mode:null,points:[],routes:{},terrain:false,localTerrain:false,imagery:false};
try{const saved=JSON.parse(routeStorage.getItem('gustavsvik-routes-v1')||'{}');for(const id of ['2','12'])if(Array.isArray(saved[id])&&saved[id].length===3&&saved[id].every(p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite)&&p[0]>15.18&&p[0]<15.24&&p[1]>59.23&&p[1]<59.26))state.routes[id]=saved[id]}catch{}
let localTerrain,viewer,C,outlineSource,routeEntities=[],measurement=[],last=0;
let orthophotoLayer;
async function loadOrthophoto(){
 const response=await fetch('orthophoto/metadata.json');
 if(!response.ok)throw Error('Ortofotots metadata saknas');
 const m=await response.json(),rectangle=C.Rectangle.fromDegrees(...m.bounds);
 const provider=new C.UrlTemplateImageryProvider({url:'orthophoto/{z}/{x}/{y}.webp?v=native16',
  rectangle,tilingScheme:new C.GeographicTilingScheme({rectangle,numberOfLevelZeroTilesX:m.levelZeroTilesX,numberOfLevelZeroTilesY:m.levelZeroTilesY}),
  tileWidth:m.tileSize,tileHeight:m.tileSize,minimumLevel:0,maximumLevel:m.maximumLevel,
  hasAlphaChannel:true,credit:new C.Credit('Ortofoto © Lantmäteriet · CC BY 4.0 · 2026-05-02',true)});
 orthophotoLayer=viewer.imageryLayers.addImageryProvider(provider);
 provider.errorEvent.addEventListener(()=>status('En ortofotoruta kunde inte laddas. Ladda om för att försöka igen.'));
 state.orthophoto=true;
 viewer.scene.globe.cartographicLimitRectangle=rectangle;
 viewer.scene.backgroundColor=C.Color.fromCssColorString('#0b211d');
 if(viewer.scene.skyBox)viewer.scene.skyBox.show=false;
 viewer.scene.sun.show=false;viewer.scene.moon.show=false;
}
const center=[15.2105,59.2478];
function status(message){$('status').textContent=message}
function stop(){state.playing=false;$('play').textContent=state.view==='overview'?'▶ Flyg över banan':'▶ Flyg längs hålet'}
function persist(){try{routeStorage.setItem('gustavsvik-routes-v1',JSON.stringify(state.routes))}catch{status('Flygvägen fungerar, men kunde inte sparas i webbläsaren.')}}
function clearEntities(list){list.forEach(e=>viewer.entities.remove(e));list.length=0}
function addMarker(point,label,color){return viewer.entities.add({position:C.Cartesian3.fromDegrees(...point),point:{pixelSize:10,color:C.Color.fromCssColorString(color),outlineColor:C.Color.WHITE,outlineWidth:2,heightReference:C.HeightReference.CLAMP_TO_GROUND,disableDepthTestDistance:Number.POSITIVE_INFINITY},label:{text:label,font:'14px sans-serif',fillColor:C.Color.WHITE,showBackground:true,backgroundColor:C.Color.fromCssColorString('#102c25'),pixelOffset:new C.Cartesian2(0,-25),heightReference:C.HeightReference.CLAMP_TO_GROUND,disableDepthTestDistance:Number.POSITIVE_INFINITY}})}
function routeDraw(){clearEntities(routeEntities);const pts=state.routes[state.view];if(!pts)return;pts.forEach((p,i)=>routeEntities.push(addMarker(p,['Tee','Flygpunkt','Green'][i],'#d4ee88')));routeEntities.push(viewer.entities.add({polyline:{positions:C.Cartesian3.fromDegreesArray(pts.flat()),width:3,material:C.Color.fromCssColorString('#d4ee88'),clampToGround:true}}))}
function update(){document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-pressed',String(b.dataset.view===state.view))});$('map-title').textContent=state.view==='overview'?'Hela banan':'Hål '+state.view;$('route-panel').hidden=state.view==='overview';$('play').disabled=!state.ready||(state.view!=='overview'&&!state.routes[state.view]);$('progress').disabled=$('play').disabled;$('export').disabled=!Object.keys(state.routes).length;$('route-help').textContent=state.routes[state.view]?'Manuellt markerad flygväg. Kontrollera tee och green mot klubbens banguide.':'Hålens koordinater behöver bekräftas. Klicka ut tee, en punkt längs hålet och green i kartan.';$('edit-route').textContent=state.routes[state.view]?'Markera om flygvägen':'Markera tee → green'}
function reset(top=false){stop();state.progress=0;$('progress').value=0;const pts=state.routes[state.view];let target=center,range=1400;if(pts){target=pts[1];range=650}viewer.camera.lookAt(C.Cartesian3.fromDegrees(...target,localTerrain?.sample(...target)??50),new C.HeadingPitchRange(C.Math.toRadians(10),C.Math.toRadians(top?-90:-48),range));viewer.camera.lookAtTransform(C.Matrix4.IDENTITY);viewer.scene.requestRender();$('time').textContent='0:00 / 0:24'}
function selectView(id){if(!['overview','2','12'].includes(id))throw Error('Ogiltig vy');state.view=id;state.mode=null;state.points=[];clearEntities(measurement);$('measure').setAttribute('aria-pressed','false');routeDraw();update();reset();status(id==='overview'?'Utforska fritt eller starta flygningen.':state.routes[id]?'Manuellt markerad flygväg – redo att testa.':'Markera hålets tee och green för att testa flygningen.');return {view:id,hasRoute:!!state.routes[id]}}
function applyFlight(t){if(state.view==='overview'){viewer.camera.lookAt(C.Cartesian3.fromDegrees(...center,localTerrain?.sample(...center)??50),new C.HeadingPitchRange(C.Math.toRadians(10+t*150),C.Math.toRadians(-42),1250))}else{const p=state.routes[state.view];if(!p)return;const seg=Math.min(1,Math.floor(t*2)),u=Math.min(1,t*2-seg),a=p[seg],b=p[seg+1],target=[a[0]+(b[0]-a[0])*u,a[1]+(b[1]-a[1])*u];const heading=Math.atan2((p[2][0]-p[0][0])*Math.cos(C.Math.toRadians(target[1])),p[2][1]-p[0][1]);const carto=C.Cartographic.fromDegrees(...target);const height=localTerrain?.sample(...target)??viewer.scene.globe.getHeight(carto)??50;viewer.camera.lookAt(C.Cartesian3.fromDegrees(...target,height+8),new C.HeadingPitchRange(heading,C.Math.toRadians(-38),190))}viewer.camera.lookAtTransform(C.Matrix4.IDENTITY);viewer.scene.requestRender();$('progress').value=Math.round(t*1000);$('time').textContent='0:'+String(Math.floor(t*24)).padStart(2,'0')+' / 0:24'}
function frame(now){if(state.playing){state.progress=Math.min(1,state.progress+(now-last)/24000);applyFlight(state.progress);if(state.progress===1)stop()}last=now;requestAnimationFrame(frame)}
async function boot(){if(!window.Cesium)throw Error('3D-motorn kunde inte laddas. Kontrollera internetanslutningen och ladda om.');C=window.Cesium;C.Ion.defaultAccessToken='';viewer=new C.Viewer('map',{baseLayer:false,baseLayerPicker:false,geocoder:false,homeButton:false,sceneModePicker:false,navigationHelpButton:false,timeline:false,animation:false,fullscreenButton:false,infoBox:false,selectionIndicator:false,requestRenderMode:true,maximumRenderTimeChange:Infinity});viewer.resolutionScale=Math.min(devicePixelRatio,1.5)/devicePixelRatio;viewer.scene.globe.baseColor=C.Color.fromCssColorString('#254739');viewer.scene.skyAtmosphere.show=false;viewer.scene.globe.enableLighting=false;viewer.scene.screenSpaceCameraController.minimumZoomDistance=70;reset();
 await loadOrthophoto();
 try{localTerrain=await GustavsvikTerrain.create(C);viewer.terrainProvider=localTerrain.provider;state.terrain=true;state.localTerrain=true;$('terrain-source').textContent='Lantmäteriet · 1 m källdata';viewer.terrainProvider.errorEvent.addEventListener(e=>{console.error('Terrain:',e.message);status('Höjddata kunde inte laddas fullt ut.');});reset();}catch(e){console.error(e);$('terrain-source').textContent='Höjdmodellen kunde inte laddas';status('Din höjdmodell saknas i vyn. Plan mark visas.');}

 try{const data=await fetch('course.geojson').then(r=>{if(!r.ok)throw Error();return r.json()});outlineSource=await C.GeoJsonDataSource.load(data,{clampToGround:true,fill:C.Color.fromCssColorString('#d4ee88').withAlpha(.12),stroke:C.Color.fromCssColorString('#d4ee88'),strokeWidth:1});await viewer.dataSources.add(outlineSource);outlineSource.show=false}catch{$('outlines').disabled=true}
 state.ready=true;update();status(state.orthophoto?(state.localTerrain?'Ortofoto 2 maj 2026 · Lantmäteriets höjdmodell':'Ortofoto 2 maj 2026 · höjdmodellen saknas'): 'Lantmäteriets ortofoto saknas i vyn');requestAnimationFrame(frame);
 viewer.screenSpaceEventHandler.setInputAction(click=>{if(!state.mode)return;const ray=viewer.camera.getPickRay(click.position),pos=viewer.scene.globe.pick(ray,viewer.scene);if(!pos)return;const c=C.Cartographic.fromCartesian(pos),p=[C.Math.toDegrees(c.longitude),C.Math.toDegrees(c.latitude)];if(p[0]<15.18||p[0]>15.24||p[1]<59.23||p[1]>59.26){status('Markera inom Gustavsviksbanans område.');return}state.points.push(p);measurement.push(addMarker(p,state.mode==='route'?['Tee','Flygpunkt','Green'][state.points.length-1]:String(state.points.length),'#ffffff'));if(state.mode==='route'){status(['','Klicka en punkt längs hålet.','Klicka på green.'][state.points.length]||'Flygvägen är markerad.');if(state.points.length===3){state.routes[state.view]=state.points.slice();persist();state.mode=null;clearEntities(measurement);routeDraw();update();status('Flygvägen sparad i denna webbläsare. Tryck på Flyg längs hålet.')}}else if(state.points.length===2){const a=C.Cartographic.fromDegrees(...state.points[0]),b=C.Cartographic.fromDegrees(...state.points[1]);const metres=new C.EllipsoidGeodesic(a,b).surfaceDistance;measurement.push(viewer.entities.add({polyline:{positions:C.Cartesian3.fromDegreesArray(state.points.flat()),width:3,material:C.Color.WHITE,clampToGround:true}}));status('Kartavstånd: cirka '+Math.round(metres)+' m · ingen lutningskorrigering');state.mode=null;$('measure').setAttribute('aria-pressed','false')}},C.ScreenSpaceEventType.LEFT_CLICK);
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>selectView(b.dataset.view));$('reset').onclick=()=>reset();$('relief').onclick=()=>{const show=$('relief').getAttribute('aria-pressed')!=='true';$('relief').setAttribute('aria-pressed',String(show));$('relief').textContent=show?'Visa flygbild':'Visa terräng';for(let i=0;i<viewer.imageryLayers.length;i++)viewer.imageryLayers.get(i).alpha=show?0:1;viewer.scene.globe.enableLighting=false;viewer.scene.globe.material=show?C.Material.fromType('ElevationContour',{color:C.Color.fromCssColorString('#183e32'),spacing:2,width:1.5}):undefined;viewer.scene.globe.baseColor=C.Color.fromCssColorString('#91b399');viewer.scene.requestRender()};$('top').onclick=()=>reset(true);$('outlines').onchange=e=>{if(outlineSource){outlineSource.show=e.target.checked;viewer.scene.requestRender()}};$('play').onclick=()=>{if(state.playing)stop();else{state.mode=null;state.points=[];clearEntities(measurement);$('measure').setAttribute('aria-pressed','false');if(state.progress>=1)state.progress=0;state.playing=true;$('play').textContent='Ⅱ Pausa flygningen'}};$('progress').oninput=e=>{stop();state.progress=Number(e.target.value)/1000;applyFlight(state.progress)};$('show-guide').onclick=()=>{const id=state.view;if(id==='overview'){status('Välj hål 2 eller 12 för att visa klubbens banguide.');return}const o=$('guide-overlay');$('guide-image').src='guides/hole-'+id+'.png';$('guide-caption').textContent='Klubbens banguide · hål '+id;o.hidden=false;viewer.scene.requestRender()};$('close-guide').onclick=()=>{$('guide-overlay').hidden=true};$('edit-route').onclick=()=>{reset(true);state.mode='route';state.points=[];clearEntities(measurement);clearEntities(routeEntities);status('Klicka på tee för hål '+state.view+'.')};$('measure').onclick=()=>{stop();state.points=[];clearEntities(measurement);state.mode=state.mode==='measure'?null:'measure';$('measure').setAttribute('aria-pressed',String(state.mode==='measure'));status(state.mode?'Klicka på två punkter för att mäta kartavstånd.':'Mätning avbruten.');routeDraw()};$('export').onclick=()=>{const blob=new Blob([JSON.stringify({type:'FeatureCollection',features:Object.entries(state.routes).map(([hole,coordinates])=>({type:'Feature',properties:{hole,source:'Manuellt markerad i prototyp',verified:false},geometry:{type:'LineString',coordinates}}))},null,2)],{type:'application/geo+json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='gustavsvik-flygvagar.geojson';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};viewer.canvas.addEventListener('pointerdown',()=>stop());viewer.canvas.addEventListener('wheel',()=>stop(),{passive:true});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
 if(document.modelContext?.registerTool){const life=new AbortController();Promise.resolve(document.modelContext.registerTool({name:'select_gustavsvik_view',description:'Välj översikten eller provhål 2 eller 12 i kartan.',inputSchema:{type:'object',properties:{view:{type:'string',enum:['overview','2','12']}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>selectView(input.view)},{signal:life.signal})).catch(()=>{});window.addEventListener('pagehide',()=>life.abort(),{once:true})}
 window.gustavsvik={state,viewer,selectView};
}
boot().catch(e=>{$('error').hidden=false;$('error').textContent='Kartan kunde inte startas. '+e.message;status('Kartan är inte redo.');console.error(e)});
